import React, { useState } from 'react';
import { useDropzone } from 'react-dropzone';

import '../../CSS/AddProduct.css';

const AddProduct = () => {
  const [collections, setCollections] = useState(['Sawariya', 'Rangrez', 'Gulzaar']);
  const [selectedCollection, setSelectedCollection] = useState('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('');
  const [subcategory, setSubcategory] = useState('');
  const [mainImage, setMainImage] = useState(null);
  const [mainImagePreview, setMainImagePreview] = useState(null);
  const [thumbnails, setThumbnails] = useState([]);
  const [thumbnailPreviews, setThumbnailPreviews] = useState([]);
  const [colorVariants, setColorVariants] = useState([]);
  const [price, setPrice] = useState('');
  const [discount, setDiscount] = useState('');
  const [sizes, setSizes] = useState([]);
  const [tags, setTags] = useState([]);

  const sizeOptions = ['38', '40', '42', '44'];
  const tagOptions = ['Bestseller', 'Exclusive', 'Is store'];
  const categoryOptions = ['Festive wear', 'Occasion wear', 'Day Wear'];
  const subcategoryOptions = [
    'Anarkali', 'Sharara Suits', 'Indo Western', 'Fusion wear',
    'Coord-sets', 'Kaftans', 'Dhoti Suits', 'Suits', 'Dress'
  ];

  const onDropMainImage = (acceptedFiles) => {
    const file = acceptedFiles[0];
    setMainImage(file);
    setMainImagePreview(URL.createObjectURL(file));
  };

  const onDropThumbnails = (acceptedFiles) => {
    setThumbnails(acceptedFiles);
    setThumbnailPreviews(acceptedFiles.map(file => URL.createObjectURL(file)));
  };

  const addColorVariant = () => {
    setColorVariants([...colorVariants, { colorName: '', images: [], previews: [] }]);
  };

  const updateColorVariant = (index, field, value) => {
    const updatedVariants = [...colorVariants];
    updatedVariants[index][field] = value;
    setColorVariants(updatedVariants);
  };

  const onDropColorImages = (index, acceptedFiles) => {
    const updatedVariants = [...colorVariants];
    updatedVariants[index].images = acceptedFiles;
    updatedVariants[index].previews = acceptedFiles.map(file => URL.createObjectURL(file));
    setColorVariants(updatedVariants);
  };

  const toggleSize = (size) => {
    setSizes(prev => prev.includes(size) ? prev.filter(s => s !== size) : [...prev, size]);
  };

  const toggleTag = (tag) => {
    setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const handleSave = () => {
    const productData = {
      collection: selectedCollection,
      title,
      description,
      category,
      subcategory,
      price,
      discount,
      sizes,
      tags,
      createdAt: new Date().toLocaleString()
    };
    console.log('Product saved:', productData);
    alert('Product saved successfully!');
  };

  // UseDropzone for Main Image
  const { getRootProps: getMainImageRootProps, getInputProps: getMainImageInputProps } = useDropzone({
    onDrop: onDropMainImage,
    accept: 'image/*',
    multiple: false,
  });

  // UseDropzone for Thumbnails
  const { getRootProps: getThumbnailsRootProps, getInputProps: getThumbnailsInputProps } = useDropzone({
    onDrop: onDropThumbnails,
    accept: 'image/*',
    multiple: true,
  });

  // UseDropzone for Color Images
  const getColorImagesDropzone = (index) => {
    return useDropzone({
      onDrop: (files) => onDropColorImages(index, files),
      accept: 'image/*',
      multiple: true,
    });
  };

  return (
    <div className="add-product-container">
      <h2>Add New Product</h2>
      <div className="form-columns">
        {/* Left Column */}
        <div className="form-column">
          <div className="form-group">
            <label>Collection:</label>
            <select value={selectedCollection} onChange={e => setSelectedCollection(e.target.value)}>
              <option value="">Select Collection</option>
              {collections.map(col => <option key={col}>{col}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Title:</label>
            <input type="text" value={title} onChange={e => setTitle(e.target.value)} />
          </div>

          <div className="form-group">
            <label>Description:</label>
            <textarea value={description} onChange={e => setDescription(e.target.value)} />
          </div>

          <div className="form-group">
            <label>Category:</label>
            <select value={category} onChange={e => setCategory(e.target.value)}>
              <option value="">Select Category</option>
              {categoryOptions.map(cat => <option key={cat}>{cat}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Subcategory:</label>
            <select value={subcategory} onChange={e => setSubcategory(e.target.value)}>
              <option value="">Select Subcategory</option>
              {subcategoryOptions.map(sub => <option key={sub}>{sub}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Price:</label>
            <input type="number" value={price} onChange={e => setPrice(e.target.value)} />
          </div>

          <div className="form-group">
            <label>Discount:</label>
            <input type="number" value={discount} onChange={e => setDiscount(e.target.value)} />
          </div>

          <div className="form-group">
            <label>Sizes Available:</label>
            {sizeOptions.map(size => (
              <label key={size}>
                <input type="checkbox" checked={sizes.includes(size)} onChange={() => toggleSize(size)} />
                {size}
              </label>
            ))}
          </div>

          <div className="form-group">
            <label>Tags:</label>
            {tagOptions.map(tag => (
              <label key={tag}>
                <input type="checkbox" checked={tags.includes(tag)} onChange={() => toggleTag(tag)} />
                {tag}
              </label>
            ))}
          </div>
        </div>

        {/* Right Column */}
        <div className="form-column">
          <div className="form-group">
            <label>Main Image:</label>
            <div className="dropzone" {...getMainImageRootProps()}>
              <input {...getMainImageInputProps()} />
              <p>Drag & drop main image here, or click to select</p>
            </div>
            {mainImagePreview && <img src={mainImagePreview} alt="Main Preview" className="preview-image" />}
          </div>

          <div className="form-group">
            <label>Thumbnails (4):</label>
            <div className="dropzone" {...getThumbnailsRootProps()}>
              <input {...getThumbnailsInputProps()} />
              <p>Drag & drop thumbnails here, or click to select</p>
            </div>
            <div className="preview-images">
              {thumbnailPreviews.map((img, index) => (
                <img key={index} src={img} alt={`Thumbnail ${index + 1}`} className="preview-image" />
              ))}
            </div>
          </div>

          <div className="form-group">
            <label>Color Variants:</label>
            {colorVariants.map((variant, index) => {
              const { getRootProps, getInputProps } = getColorImagesDropzone(index);
              return (
                <div key={index} className="color-variant">
                  <input
                    type="text"
                    placeholder="Color Name"
                    value={variant.colorName}
                    onChange={e => updateColorVariant(index, 'colorName', e.target.value)}
                  />
                  <div className="dropzone" {...getRootProps()}>
                    <input {...getInputProps()} />
                    <p>Drag & drop color images here, or click to select</p>
                  </div>
                  <div className="preview-images">
                    {variant.previews && variant.previews.map((img, idx) => (
                      <img key={idx} src={img} alt={`Color ${index + 1} Image ${idx + 1}`} className="preview-image" />
                    ))}
                  </div>
                </div>
              );
            })}
            <button type="button" onClick={addColorVariant}>Add More Colors</button>
          </div>
        </div>
      </div>

      <button className="save-btn" onClick={handleSave}>Save Product</button>
    </div>
  );
};

export default AddProduct;
